INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023805',2336,76,'P2','Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','1) Julgue o item a seguir, referente à contabilidade de custos. No custeio por absorção, são incorporados ao valor dos produtos apenas os custos variáveis, enquanto os custos fixos são tratados como despesa do período.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Errado',2026,1,NULL,NULL,'{"regra": "A contabilidade de custos mensura e analisa custos, servindo tanto à mensuração contábil quanto ao planejamento, controle e tomada de decisão gerencial.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Errado."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Errado — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023944',2337,76,'P2','Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','2) Considerando as metodologias de custeio para fins gerenciais, julgue o item subsequente. Considere que os custos de fabricação de um produto, em reais, sejam expressos pela equação Y = 10.000 + 5X, em que Y é o custo total de produção e X, o volume produzido. Nessas condições, os custos fixos totais de produção são de R$ 10.000 e os custos variáveis unitários são de R$ 5,00 por unidade produzida.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Certo',2026,2,NULL,NULL,'{"regra": "A contabilidade de custos mensura e analisa custos, servindo tanto à mensuração contábil quanto ao planejamento, controle e tomada de decisão gerencial.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Certo."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Certo — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Contabilidade de Custos, Financeira e Gerencial"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992113',2338,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','FGV - Bach (CFC)/CFC/1º Exame de Suficiência/2026','Caderno Contabilidade de Custos 2','3) A companhia Indústria “K” S.A. possui, em sua planta de fábrica, os setores de Montagem (30 m²) e Acabamento (50 m²). Em determinado período, o custo com a energia elétrica da produção foi de R$ 25.000,00. O critério de rateio adotado pela empresa é por área ocupada. Sendo assim, o valor alocado ao setor de Montagem é de','[["A", "R$ 15.625,00."], ["B", "R$ 9.375,00."], ["C", "R$ 12.500,00."], ["D", "R$ 10.000,00."]]'::jsonb,'B',2026,3,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — R$ 9.375,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3994436',2339,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','FGV - AFCE (TCE-SC)/TCE SC/Ciências Contábeis/2026','Caderno Contabilidade de Custos 2','4) Uma entidade expandiu as suas operações em janeiro de 2026. Para isso, realizou as seguintes transações: Pagamento, antecipado, do seguro anual das instalações fabris: R$ 6.000,00. Pagamento dos honorários de empresa de consultoria por serviço realizado durante o mês de janeiro: R$ 8.000,00. Compra de móveis e utensílios à vista: R$ 50.000,00. Compra de veículo, para pagamento em 120 dias: R$ 60.000,00. De acordo com a terminologia da contabilidade de custos, em janeiro de 2026, a entidade realizou investimento de','[["A", "R$ 50.000,00."], ["B", "R$ 56.000,00."], ["C", "R$ 110.000,00."], ["D", "R$ 116.000,00."], ["E", "R$ 124.000,00."]]'::jsonb,'D',2026,4,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 116.000,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3995464',2340,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','CEBRASPE (CESPE) - TNS (SEMA AM)/SEMA AM/Contabilidade/2026','Caderno Contabilidade de Custos 2','5) No que se refere à classificação e às nomenclaturas de custos, julgue os itens a seguir. I. Os custos primários representam a soma de matéria-prima com mão de obra direta. II. A embalagem é um custo direto, mas não primário. III. Os custos de transformação representam a soma de todos os custos de produção, exceto os relativos a matérias-primas e a outros eventuais itens adquiridos, e a remuneração paga aos seus empregados. Assinale a opção correta.','[["A", "Apenas o item I está certo."], ["B", "Apenas o item III está certo."], ["C", "Apenas os itens I e II estão certos."], ["D", "Apenas os itens II e III estão certos."], ["E", "Todos os itens estão certos."]]'::jsonb,'E',2026,5,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — Todos os itens estão certos.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3999864',2341,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','Instituto AOCP - PEBTT (IF CE)/IF CE/Ciências Contábeis/2026','Caderno Contabilidade de Custos 2','6) Em fevereiro de 2026, uma fábrica dedicada à produção de tênis esportivos e chuteiras registrou os seguintes gastos: aluguel do imóvel da fábrica, no valor de R$ 10.000; salário do gerente de produção, no valor de R$ 8.000; consumo de embalagens, no valor de R$ 2.000; consumo de matéria-prima, no montante de R$ 50.000; e seguro da fábrica, no valor de R$ 1.000. Considerando os conceitos de custos fixos e variáveis, assinale a alternativa que apresenta corretamente os custos classificados como fixos incorridos pela fábrica no período.','[["A", "Salário do gerente de produção, embalagens e matéria-prima."], ["B", "Aluguel da fábrica, salário do gerente de produção e seguro da fábrica."], ["C", "Matéria-prima, embalagens e aluguel da fábrica."], ["D", "Salário do gerente de produção, matéria-prima e seguro da fábrica."], ["E", "Aluguel da fábrica, embalagens e seguro da fábrica."]]'::jsonb,'B',2026,6,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — Aluguel da fábrica, salário do gerente de produção e seguro da fábrica.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3999866',2342,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','Instituto AOCP - PEBTT (IF CE)/IF CE/Ciências Contábeis/2026','Caderno Contabilidade de Custos 2','7) Em março de 2026, uma fábrica registrou os gastos relacionados à sua produção, sendo R$ 180.000 referentes à matéria-prima, R$ 120.000 correspondentes à mão de obra direta e R$ 300.000 relacionados aos custos indiretos de fabricação. Com base na classificação de custo primário e custo de transformação, assinale a alternativa que apresenta corretamente os valores desses custos.','[["A", "R$ 300.000 para o custo primário e R$ 420.000 para o custo de transformação."], ["B", "R$ 180.000 para o custo primário e R$ 300.000 para o custo de transformação."], ["C", "R$ 300.000 para o custo primário e R$ 300.000 para o custo de transformação."], ["D", "R$ 180.000 para o custo primário e R$ 420.000 para o custo de transformação."], ["E", "R$ 420.000 para o custo primário e R$ 300.000 para o custo de transformação."]]'::jsonb,'A',2026,7,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — R$ 300.000 para o custo primário e R$ 420.000 para o custo de transformação.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
