INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4147384',2345,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','CEBRASPE (CESPE) - AFRM (Pref Porto Velho)/Pref Porto Velho/2026','Caderno Contabilidade de Custos 2','10) Um analista de custos de certa indústria de móveis está revisando a classificação dos gastos incorridos no processo produtivo. Durante a análise, o analista verifica que a madeira utilizada na fabricação das mesas pode ser identificada diretamente em cada unidade produzida. Na situação hipotética precedente, a madeira utilizada na fabricação das mesas é classificada como','[["A", "perda operacional."], ["B", "custo indireto de fabricação."], ["C", "despesa direta."], ["D", "despesa comercial."], ["E", "custo direto."]]'::jsonb,'E',2026,10,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — custo direto.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4147386',2346,90,'P1','Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc','CEBRASPE (CESPE) - AFRM (Pref Porto Velho)/Pref Porto Velho/2026','Caderno Contabilidade de Custos 2','11) Uma fábrica de estruturas metálicas está organizada em três departamentos: o de corte, o de montagem e o de manutenção. O departamento de manutenção presta serviços aos demais departamentos produtivos, mas não atua diretamente na fabricação dos produtos. Nessa situação hipotética, na departamentalização dos custos, os custos de manutenção','[["A", "devem ser registrados como receita operacional."], ["B", "devem ser apropriados aos departamentos produtivos por meio de critérios de rateio."], ["C", "devem compor exclusivamente o patrimônio líquido."], ["D", "não influenciam o custo dos produtos."], ["E", "devem ser registrados diretamente como despesa do período."]]'::jsonb,'B',2026,11,NULL,NULL,'{"regra": "Custos diretos são identificáveis ao objeto de custo; indiretos exigem rateio. Custos fixos não variam no total dentro da faixa relevante; variáveis acompanham o volume.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — devem ser apropriados aos departamentos produtivos por meio de critérios de rateio.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Classificação de Custos: Variável, Fixo, Direto, Indireto, Primário, etc"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3913237',2347,84,'P1','Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo.','FADESP - AFRE PA/SEFA PA/2026','Caderno Contabilidade de Custos 2','12) A empresa Igarapé Miri Industrial S.A atua no setor metalmecânico e possui duas frentes produtivas bem definidas. A primeira refere-se à fabricação contínua e padronizada de componentes metálicos utilizados na indústria automotiva, com produção em larga escala e processos sequenciais. A segunda frente corresponde à produção sob encomenda de equipamentos especiais, desenvolvidos conforme especificações técnicas exclusivas de cada cliente, com projetos não repetitivos e produção intermitente. Diante da necessidade de garantir coerência entre o sistema produtivo e o sistema de acumulação de custos, a controladoria da Igarapé Miri Industrial S.A avalia a adoção simultânea dos sistemas de custeio por processos e por ordem de produção. Com base nos fundamentos da contabilidade de custos e nos sistemas de acumulação de custos aplicáveis à produção contínua e à produção por encomenda, considere as assertivas a seguir: I. A coexistência, em uma mesma empresa, dos sistemas de custeio por processos e por ordem de produção é conceitualmente admissível, desde que cada sistema esteja vinculado a linhas produtivas distintas e estruturalmente compatíveis com suas características operacionais. II. A escolha entre custeio por processos e custeio por ordem de produção não afeta os princípios contábeis nem o tratamento fiscal dos custos, mas altera substancialmente os critérios de mensuração, acumulação e apropriação dos custos aos produtos. III. No sistema de custeio por processos, os custos são acumulados por departamentos ou centros de custos, e o custo unitário é obtido mediante a divisão do custo total acumulado no período pela quantidade de unidades equivalentes produzidas. IV. No sistema de custeio por ordem de produção, a identificação individual dos custos por lote ou encomenda é inviável, razão pela qual se faz necessária a utilização de critérios médios de rateio semelhantes aos empregados no custeio por processos. Está correto o que se afirma em','[["A", "I e II, apenas."], ["B", "I, II e III, apenas."], ["C", "I e III, apenas."], ["D", "II e IV, apenas."], ["E", "II, III e IV, apenas."]]'::jsonb,'B',2026,12,NULL,NULL,'{"regra": "Produção por processo é adequada à produção contínua e homogênea; por ordem, à produção identificável por encomenda/lote. Unidades equivalentes ajustam a produção em elaboração ao grau de acabamento.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo..", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — I, II e III, apenas.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo."}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3951287',2348,84,'P1','Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo.','Instituto Consulplan - Ana (CREFITO 5)/CREFITO 5/Contábil/2026','Caderno Contabilidade de Custos 2','13) Determinada sociedade empresária industrial fabrica tapetes de banheiro. No mês de novembro de 2025, o departamento de custos dessa empresa possuía as seguintes informações sobre a produção: Quantidade de unidades de tapetes com fabricação iniciada no mês de novembro: 30.000; Quantidade de unidades de tapetes com fabricação finalizada no mês de novembro: 10.000; e Porcentagem de conclusão das unidades que não foram finalizadas: 70%. Com base somente nessas informações, o total de produção equivalente é:','[["A", "14.000."], ["B", "20.000."], ["C", "21.000."], ["D", "24.000."]]'::jsonb,'D',2026,13,NULL,NULL,'{"regra": "Produção por processo é adequada à produção contínua e homogênea; por ordem, à produção identificável por encomenda/lote. Unidades equivalentes ajustam a produção em elaboração ao grau de acabamento.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo..", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — 24.000.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo."}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023807',2349,84,'P1','Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo.','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','14) Julgue o item a seguir, referente à contabilidade de custos. O custeio por ordem de produção é adequado para empresas que produzem sob encomenda, enquanto o custeio por processo é indicado para produção contínua e padronizada.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Certo',2026,14,NULL,NULL,'{"regra": "Produção por processo é adequada à produção contínua e homogênea; por ordem, à produção identificável por encomenda/lote. Unidades equivalentes ajustam a produção em elaboração ao grau de acabamento.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo..", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Certo."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Certo — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Equivalente de Produção. Custo por Ordem e por Processo."}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3883612',2350,84,'P1','Contabilidade de Custos - Departamentalização','CEBRASPE (CESPE) - AFRE (SEFAZ RN)/SEFAZ RN/2026','Caderno Contabilidade de Custos 2','15) Uma indústria que possui três departamentos — produção, manutenção e logística — decidiu alocar os custos do departamento de manutenção para os demais departamentos. Nessa situação hipotética, o critério de rateio adequado consiste em','[["A", "alocar todos os custos de manutenção apenas no departamento de produção."], ["B", "ratear os custos proporcionalmente ao faturamento de cada departamento."], ["C", "ratear os custos proporcionalmente ao volume de ordens de serviços atendidas pelo departamento de manutenção."], ["D", "não alocar os custos de manutenção, pois eles são considerados fixos e não afetam a produção."], ["E", "ratear os custos igualmente entre todos os departamentos, independentemente do uso de manutenção."]]'::jsonb,'C',2026,15,NULL,NULL,'{"regra": "Na departamentalização, custos indiretos são acumulados por departamentos/centros de custos e depois apropriados aos produtos mediante critérios de rateio coerentes.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — ratear os custos proporcionalmente ao volume de ordens de serviços atendidas pelo departamento de manutenção.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Departamentalização"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023754',2351,84,'P1','Contabilidade de Custos - Departamentalização','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','16) Julgue o item a seguir, referente à contabilidade de custos. Na departamentalização, os custos indiretos são inicialmente atribuídos aos departamentos e, posteriormente, rateados entre os produtos com base em critérios de alocação.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Certo',2026,16,NULL,NULL,'{"regra": "Na departamentalização, custos indiretos são acumulados por departamentos/centros de custos e depois apropriados aos produtos mediante critérios de rateio coerentes.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Certo."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Certo — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Departamentalização"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3385451',2352,84,'P1','Contabilidade de Custos - Departamentalização','CEBRASPE (CESPE) - AFP (SEFAZ RJ)/SEFAZ RJ/Contábil Financeira/2025','Caderno Contabilidade de Custos 2','17) Julgue os itens que se seguem, a respeito do uso da departamentalização na contabilidade de custos. I Não há distinção entre os conceitos de departamento e centro de custos para fins de alocação dos custos aos produtos por meio da departamentalização. II Os custos originados em um departamento não podem ser transferidos para outro departamento sem a definição de um critério único de rateio para realizar a operação. III Uma das vantagens da departamentalização é tornar mais racional o processo de distribuição dos custos indiretos aos produtos. Assinale a opção correta.','[["A", "Apenas o item II está certo."], ["B", "Apenas o item III está certo."], ["C", "Apenas os itens I e II estão certos."], ["D", "Apenas os itens I e III estão certos."], ["E", "Todos os itens estão certos."]]'::jsonb,'B',2025,17,NULL,NULL,'{"regra": "Na departamentalização, custos indiretos são acumulados por departamentos/centros de custos e depois apropriados aos produtos mediante critérios de rateio coerentes.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — Apenas o item III está certo.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Departamentalização"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3639109',2353,84,'P1','Contabilidade de Custos - Departamentalização','CEBRASPE (CESPE) - AFT (SEFAZ SE)/SEFAZ SE/Geral/2025','Caderno Contabilidade de Custos 2','18) Assinale a opção em que é corretamente descrita uma etapa do processo de alocação de custos aos produtos por meio da departamentalização.','[["A", "utilização do custeio variável para a alocação final dos custos aos produtos"], ["B", "transferência para os produtos dos custos indiretos acumulados nos departamentos de serviços, com base em critérios de rateio que considerem a forma como esses produtos fizeram uso dos serviços dos referidos departamentos"], ["C", "escolha da sequência de rateio dos custos acumulados nos departamentos de produção, com vistas à sua distribuição aos demais departamentos"], ["D", "transferência dos custos diretos aos departamentos antes de sua alocação aos produtos"], ["E", "classificação dos departamentos em dois grandes grupos: um que contemple os departamentos que promovem diretamente modificações sobre o produto que está sendo fabricado; e outro que abranja os departamentos que não recebem o produto, mas que oferecem o devido suporte ao processo produtivo"]]'::jsonb,'E',2025,18,NULL,NULL,'{"regra": "Na departamentalização, custos indiretos são acumulados por departamentos/centros de custos e depois apropriados aos produtos mediante critérios de rateio coerentes.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Departamentalização.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — classificação dos departamentos em dois grandes grupos: um que contemple os departamentos que promovem diretamente modificações sobre o produto que está sendo fabricado; e outro que abranja os departamentos que não recebem o produto, mas que oferecem o devido suporte ao processo produtivo", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Departamentalização"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3913236',2354,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','FADESP - AFRE PA/SEFA PA/2026','Caderno Contabilidade de Custos 2','19) - Produção: 3.000 unidades totalmente acabadas. - Custos Variáveis: R$ 48.000,00. - Custos Fixos: R$ 60.000,00. - Despesas Variáveis: R$ 20.000,00. - Despesas Fixas: R$ 16.000,00. - Não há estoques iniciais e finais de produtos em elaboração. - Não há estoques iniciais de produtos acabados. - Vendas Líquidas: 2.500 unidades a R$ 80,00 cada, totalizando uma receita de R$ 200.000,00. Não satisfeito apenas com a informação sobre o custo da produção vendida (CPV), a diretoria da empresa industrial Augusto Corrêa Ltda, por necessidade de informações gerenciais, solicitou ao contador informações referentes à margem de contribuição das plantas ornamentais daquele período. Para atender a esta solicitação, o contador apurou o lucro líquido baseado no método de custeio variável. Então, com os mesmos dados da questão anterior, sobre a produção e comercialização de plantas ornamentais para o dia das mães, é correto afirmar que a industrial Augusto Corrêa Ltda auferiu um lucro líquido de','[["A", "R$ 140.000,00."], ["B", "R$ 160.000,00."], ["C", "R$ 150.000,00."], ["D", "R$ 64.000,00."], ["E", "R$ 74.000,00."]]'::jsonb,'D',2026,19,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 64.000,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3923592',2355,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','FEPESE - Cont (CIDASC)/CIDASC/2026','Caderno Contabilidade de Custos 2','20) Caso 3 Para responder à questão, considere que a companhia Peneiras produz apenas dois produtos: tendas e barracas; não há qualquer tipo de tributação e há as seguintes informações: Informação Tenda Barraca Preço de venda (por unidade – R$) 100 120 Quantidades produzidas (em unidades) 200 200 Quantidades vendidas (em unidades) 170 160 Custos variáveis (por unidade – R$) 30 40 Custos fixos no período Valores (R$) Supervisão da produção 3.000 Energia elétrica 2.000 Outros 1.000 O valor do lucro bruto, pelo sistema de custeio variável, foi de:','[["A", "R$ 5.500."], ["B", "R$ 15.800."], ["C", "R$ 16.200."], ["D", "R$ 18.700."], ["E", "R$ 19.500"]]'::jsonb,'D',2026,20,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 18.700.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3930410',2356,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','FCC - ALegis (ALMS)/ALMS/Contador/2026','Caderno Contabilidade de Custos 2','21) Uma empresa produz veículos. Para fins de absorção de custos, a política adotada por essa empresa é lançar os custos e despesas fixos diretamente em contas de resultado. Nesse caso, está sendo utilizado o método de custeio','[["A", "por resultado."], ["B", "variável."], ["C", "ABC."], ["D", "por absorção."], ["E", "constante."]]'::jsonb,'B',2026,21,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — variável.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023950',2357,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','22) Considerando as metodologias de custeio para fins gerenciais, julgue o item subsequente. O método do custeio variável considera apenas custos e despesas variáveis no custo unitário do produto, o que permite a apuração da margem de contribuição absoluta e relativa e, em decorrência, a apuração do ponto de equilíbrio e de outras medidas de grande valor para fins de gestão.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Errado',2026,22,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Errado."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Errado — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3592475',2358,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','Instituto Consulplan - Ass (CISBAF)/CISBAF/Técnico Administrativo II/Contabilidade/2025','Caderno Contabilidade de Custos 2','23) Determinada sociedade empresária industrial fabrica pneus para tratores. No mês de janeiro de X1, essa empresa apresentou as seguintes informações no seu departamento de custo: Custos variáveis de produção R$ 30,00/unidade Quantidade produzida no mês de janeiro 300.000 unidades Valor de venda líquida por unidade R$ 50,00 Custos fixos R$ 400.000,00/mês Capacidade mensal de produção 310.000 unidades Despesas variáveis de produção R$ 10,00/unidade Quantidade vendida no mês 100.000 unidades Despesas administrativas R$ 80.000,00/mês Com base somente nessas informações, é correto afirmar que o resultado operacional bruto, apurado pelo método de custeio variável, no respectivo mês, é de:','[["A", "R$ 480.000,00."], ["B", "R$ 520.000,00."], ["C", "R$ 1.000.000,00."], ["D", "R$ 2.000.000,00."]]'::jsonb,'C',2025,23,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — R$ 1.000.000,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3607290',2359,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','FGV - Bach (CFC)/CFC/2º Exame de Suficiência/2025','Caderno Contabilidade de Custos 2','24) A Fazenda Laticínios Campo Verde Ltda. produz e comercializa queijos artesanais tipo minas frescal. No mês de julho de 2025, quando a empresa não possuía estoque inicial, foram produzidas 12.000 unidades de queijo. Nesse mesmo mês, vendeu 9.000 unidades a um preço unitário de R$ 25,00. Os custos variáveis totais somaram R$ 135.000,00 e os custos fixos totalizaram R$ 42.000,00. As despesas fixas totalizaram R$ 25.000,00, e as despesas variáveis com comissão aos vendedores corresponderam a 5% do valor de cada unidade vendida. Considerando os dados fornecidos e desconsiderando efeitos tributários, os lucros líquidos com as vendas em julho de 2025, utilizando, respectivamente, os métodos de custeio por absorção e custeio variável, foram de','[["A", "R$ 45.470,00 e R$ 11.750,00."], ["B", "R$ 56.000,00 e R$ 56.000,00."], ["C", "R$ 45.470,00 e R$ 112.500,00."], ["D", "R$ 56.000,00 e R$ 45.500,00."]]'::jsonb,'D',2025,24,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 56.000,00 e R$ 45.500,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3639105',2360,90,'P1','Contabilidade de Custos - Custeio Direto/Variável','CEBRASPE (CESPE) - AFT (SEFAZ SE)/SEFAZ SE/Geral/2025','Caderno Contabilidade de Custos 2','25) A utilização do método do custeio variável será preferível à do método do custeio por absorção quando a administração de uma empresa industrial tiver a intenção de','[["A", "identificar os produtos que mais contribuem para a lucratividade da empresa."], ["B", "alocar todos os custos indiretos aos produtos da empresa."], ["C", "atender às disposições do fisco quanto aos aspectos relacionados à apuração de resultados e à avaliação patrimonial da empresa."], ["D", "definir os preços mínimos dos produtos da empresa, a serem praticados em condições normais de negociação."], ["E", "calcular o custo dos produtos vendidos para fins de evidenciação na demonstração do resultado do exercício da empresa."]]'::jsonb,'A',2025,25,NULL,NULL,'{"regra": "No custeio variável, os custos variáveis de produção são apropriados aos produtos; os custos fixos de fabricação são tratados como gastos do período para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Direto/Variável.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — identificar os produtos que mais contribuem para a lucratividade da empresa.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Direto/Variável"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3930416',2361,90,'P1','Contabilidade de Custos - Margem de Contribuição','FCC - ALegis (ALMS)/ALMS/Contador/2026','Caderno Contabilidade de Custos 2','26) Atenção: Utilize as informações a seguir para responder à questão. A contabilidade de determinada empresa levantou os seguintes dados sobre a produção empresarial: Preço de venda unitário: R$ 180,00 Custos fixos unitários: R$ 77,00 Custos fixos totais: R$ 53.900,00 Custos variáveis unitários: R$ 50,00 Despesas fixas unitárias: R$ 30,00 Despesas fixas totais: R$ 21.000,00 Despesas variáveis unitárias: R$ 40,00 Quantidade vendida: 700 Com base nesses dados, a margem de contribuição unitária e a margem de contribuição total são, respectivamente,','[["A", "R$ 270,00 e R$ 189.000,00"], ["B", "-R$ 17,00 e -R$ 11.900,00"], ["C", "R$ 377,00 e R$ 263.000,00"], ["D", "R$ 90,00 e R$ 63.000,00"], ["E", "R$ 73,00 e R$ 51.100,00"]]'::jsonb,'D',2026,26,NULL,NULL,'{"regra": "A margem de contribuição corresponde à receita menos os custos e despesas variáveis e mostra quanto sobra para cobrir gastos fixos e formar o resultado.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Margem de Contribuição.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — R$ 90,00 e R$ 63.000,00", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Margem de Contribuição"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992153',2362,90,'P1','Contabilidade de Custos - Margem de Contribuição','VUNESP - Cont (CM São Roque)/CM São Roque/2026','Caderno Contabilidade de Custos 2','27) A margem de segurança é um indicador utilizado na análise custo-volume-lucro para avaliar o risco operacional de uma empresa. Considerando esse conceito, é correto afirmar que a margem de segurança','[["A", "representa o valor máximo de custos fixos que uma empresa pode suportar sem apresentar prejuízo operacional."], ["B", "corresponde ao excesso das vendas realizadas ou projetadas sobre o ponto de equilíbrio, indicando quanto as vendas podem cair antes que a empresa passe a ter prejuízo."], ["C", "representa o percentual de custos variáveis que deve ser reduzido para que a empresa alcance o ponto de equilíbrio."], ["D", "corresponde ao valor da margem de contribuição dividido pelos custos fixos totais da empresa."], ["E", "representa o valor das vendas necessárias para cobrir todos os custos fixos e variáveis da empresa."]]'::jsonb,'B',2026,27,NULL,NULL,'{"regra": "A margem de contribuição corresponde à receita menos os custos e despesas variáveis e mostra quanto sobra para cobrir gastos fixos e formar o resultado.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Margem de Contribuição.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — corresponde ao excesso das vendas realizadas ou projetadas sobre o ponto de equilíbrio, indicando quanto as vendas podem cair antes que a empresa passe a ter prejuízo.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Margem de Contribuição"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4147385',2363,90,'P1','Contabilidade de Custos - Margem de Contribuição','CEBRASPE (CESPE) - AFRM (Pref Porto Velho)/Pref Porto Velho/2026','Caderno Contabilidade de Custos 2','28) Determinada indústria produz um item que é vendido por R$ 120 a unidade, e os custos e despesas variáveis totalizam R$ 75 por unidade. Nessa situação, considerada a análise gerencial de custos, a margem de contribuição unitária do produto corresponde a','[["A", "R$ 30."], ["B", "R$ 45."], ["C", "R$ 75."], ["D", "R$ 120."], ["E", "R$ 195."]]'::jsonb,'B',2026,28,NULL,NULL,'{"regra": "A margem de contribuição corresponde à receita menos os custos e despesas variáveis e mostra quanto sobra para cobrir gastos fixos e formar o resultado.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Margem de Contribuição.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — R$ 45.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Margem de Contribuição"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4147387',2364,90,'P1','Contabilidade de Custos - Margem de Contribuição','CEBRASPE (CESPE) - AFRM (Pref Porto Velho)/Pref Porto Velho/2026','Caderno Contabilidade de Custos 2','29) Determinada empresa apresenta os seguintes dados mensais. Receita de vendas: R$ 800.000. Custos e despesas variáveis: R$ 480.000. Custos e despesas fixos: R$ 240.000. Nesse caso hipotético, de acordo com os conceitos de análise de custo × volume × lucro, o valor da margem de segurança corresponde a','[["A", "R$ 80.000."], ["B", "R$ 160.000."], ["C", "R$ 200.000."], ["D", "R$ 240.000."], ["E", "R$ 320.000."]]'::jsonb,'C',2026,29,NULL,NULL,'{"regra": "A margem de contribuição corresponde à receita menos os custos e despesas variáveis e mostra quanto sobra para cobrir gastos fixos e formar o resultado.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Margem de Contribuição.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — R$ 200.000.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Margem de Contribuição"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3908806',2365,84,'P1','Contabilidade de Custos - Alavancagem Operacional','FADESP - Ana TE (SEFA PA)/SEFA PA/Administração/2026','Caderno Contabilidade de Custos 2','30) Com base na conceituação e nos efeitos da alavancagem operacional e financeira, avalie as afirmativas abaixo: I. Quando o resultado da divisão entre a variação percentual do Lucro Líquido e a variação percentual do Lucro Antes dos Juros e Imposto de Renda (LAJIR) resulta em valor menor que 1, é possível afirmar que o Grau de Alavancagem Financeira (GAF) está contribuindo positivamente para a lucratividade. II. Compreender o Grau de Alavancagem Operacional (GAO) e Grau de Alavancagem Financeira (GAF) é útil para compreender a sensibilidade do lucro. III. Quando o resultado da divisão entre a variação percentual do Lucro Antes dos Juros e Imposto de Renda (LAJIR) e a variação percentual do Volume de Vendas resulta em 1, o Grau de Alavancagem Operacional (GAO) indica que a estrutura de custos da empresa é predominantemente variável. É (são) verdadeira(s) a(s) alternativa(s):','[["A", "I, apenas."], ["B", "I e II."], ["C", "II, apenas."], ["D", "II e III."], ["E", "III, apenas."]]'::jsonb,'D',2026,30,NULL,NULL,'{"regra": "A alavancagem operacional decorre da existência de custos e despesas fixos; o GAO mede a sensibilidade do resultado operacional às variações das vendas.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Alavancagem Operacional.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — II e III.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Alavancagem Operacional"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3930427',2366,84,'P1','Contabilidade de Custos - Alavancagem Operacional','FCC - ALegis (ALMS)/ALMS/Contador/2026','Caderno Contabilidade de Custos 2','31) A alavancagem operacional é considerada como o efeito decorrente da existência de custos e despesas fixas operacionais, que faz com que variações no volume de vendas provoquem variações mais do que proporcionais no resultado operacional. Nesse contexto, o Grau de Alavancagem Operacional (GAO) é calculado por','[["A", "custos e despesas fixas operacionais ÷ receita total de vendas."], ["B", "receita total de vendas ÷ custos e despesas variáveis totais."], ["C", "resultado operacional ÷ margem de contribuição."], ["D", "margem de contribuição ÷ lucro líquido do período."], ["E", "margem de contribuição ÷ resultado operacional."]]'::jsonb,'E',2026,31,NULL,NULL,'{"regra": "A alavancagem operacional decorre da existência de custos e despesas fixos; o GAO mede a sensibilidade do resultado operacional às variações das vendas.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Alavancagem Operacional.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — margem de contribuição ÷ resultado operacional.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Alavancagem Operacional"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3678437',2367,84,'P1','Contabilidade de Custos - Alavancagem Operacional','Instituto Darwin - Cont (CREA PB)/CREA PB/2025','Caderno Contabilidade de Custos 2','32) Na cidade existem duas empresas de copos térmicos, a empresa A obteve em vendas o valor de R$ 100.000,00, onde suas despesas variáveis foram de R$ 60.000 e seus custos fixos de R$ 20.000. Já a empresa B também obteve em vendas o valor de R$ 100.000,00, onde suas despesas variáveis foram de R$ 20.000 e seus custos fixos de R$ 60.000. Se ocorrer um aumento nas vendas em 10% em ambas as empresas:','[["A", "As duas empresas terão o mesmo resultado"], ["B", "A empresa A terá um resultado melhor por ter maior alavancagem operacional"], ["C", "A empresa A terá um resultado melhor por ter menor alavancagem operacional"], ["D", "A empresa B terá um resultado melhor por ter menor alavancagem operacional"], ["E", "A empresa B terá um resultado melhor por ter maior alavancagem operacional"]]'::jsonb,'E',2025,32,NULL,NULL,'{"regra": "A alavancagem operacional decorre da existência de custos e despesas fixos; o GAO mede a sensibilidade do resultado operacional às variações das vendas.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Alavancagem Operacional.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — A empresa B terá um resultado melhor por ter maior alavancagem operacional", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Alavancagem Operacional"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3976042',2368,84,'P1','Contabilidade de Custos - Custeio Baseado em Atividades (ABC)','FCC - AFRE GO/SEFAZ GO/2026','Caderno Contabilidade de Custos 2','33) Considere as informações a seguir para responder à questão. Uma empresa de marketing oferece dois tipos de serviços aos seus clientes: pesquisa de mercado e divulgação de produtos. Os custos diretos e o preço cobrado para cada tipo de serviço são os seguintes: Serviço Custos diretos Preço do serviço Pesquisa de mercado R$10.000 por projeto R$40.000 por projeto Divulgação de produtos R$62.400 por produto/ano R$144.000 por produto/ano Os custos indiretos anuais da empresa totalizaram R$ 1.060.000 e foram referentes às seguintes atividades: Estudo de novos mercados: R$ 100.000 por ano Análise jurídica: R$ 200.000 por ano Entrega de relatórios: R$ 760.000 por ano Os direcionadores de custos anuais dessas atividades identificados pela empresa e os percentuais consumidos por cada tipo de serviço foram: Pesquisa de Divulgação de Direcionadores mercado produtos Tempo de Estudo de novos 60% 40% mercados (horas) Número de lotes de análise 30% 70% jurídica Preparação e entrega de 20% 80% relatóriuos No ano de 2024, a empresa desenvolveu 10 projetos de pesquisa de mercado e prestou 20 serviços de divulgação de produtos no ano. Se a empresa adota o Custeio Baseado em Atividades (ABC), o lucro bruto apurado em 2024, exclusivamente para o serviço divulgação de produtos, foi, em reais:','[["A", "2.029.600"], ["B", "2.092.000"], ["C", "1.632.000"], ["D", "1.102.000"], ["E", "844.000"]]'::jsonb,'E',2026,33,NULL,NULL,'{"regra": "No ABC, os recursos são atribuídos às atividades e, depois, aos objetos de custo por meio de direcionadores que representem o consumo das atividades.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Baseado em Atividades (ABC).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — 844.000", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Baseado em Atividades (ABC)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4122877',2369,84,'P1','Contabilidade de Custos - Custeio Baseado em Atividades (ABC)','FCC - AFFE (SEFAZ CE)/SEFAZ CE/Gestão Fazendária/2026','Caderno Contabilidade de Custos 2','34) Uma empresa de tecnologia oferece dois tipos de serviços aos seus clientes: manutenção de hardware e desenvolvimento de software. Os custos diretos para cada tipo de serviço são os seguintes: Serviço Custos diretos Manutenção de hardware R$ 10.000 por atendimento Desenvolvimento de software R$ 62.400 por desenvolvimento / ano Os custos indiretos anuais da empresa totalizaram R$ 1.060.000 e foram referentes às seguintes atividades: Estudo e análise: R$ 100.000 por ano Serviços indiretos: R$ 200.000 por ano Testes de funcionalidade: R$ 760.000 por ano Os direcionadores de custos anuais dessas atividades identificados pela empresa e os percentuais consumidos por cada tipo de serviço foram: Direcionadores Manutenção de hardware Desenvolvimento de software Tempo dispendido em estudos (horas) 60% 40% Demanda por serviços indiretos 30% 70% Tempo de testes de funcionalidade 20% 80% No ano de 2025, a empresa realizou 10 serviços de manutenção de equipamentos e desenvolveu 20 softwares. Se a empresa adota o Custeio Baseado em Atividades (ABC), os custos totais da manutenção de hardware e do desenvolvimento de software no ano de 2025 foram, respectivamente, em reais:','[["A", "282.000 e 850.400"], ["B", "630.000 e 1.778.000"], ["C", "272.000 e 788.000"], ["D", "100.000 e 1.248.000"], ["E", "372.000 e 2.036.000"]]'::jsonb,'E',2026,34,NULL,NULL,'{"regra": "No ABC, os recursos são atribuídos às atividades e, depois, aos objetos de custo por meio de direcionadores que representem o consumo das atividades.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Baseado em Atividades (ABC).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é E."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "E — 372.000 e 2.036.000", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Baseado em Atividades (ABC)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3798931',2370,76,'P2','Contabilidade de Custos - Custeio Pleno (RKW)','FGV - ADTND (AMAZUL)/AMAZUL/Auditor/2026','Caderno Contabilidade de Custos 2','35) Um sistema de custeio caracteriza-se por incluir, como custo dos produtos, todos os custos e todas as despesas incorridas no período, sem distinção entre itens relacionados diretamente à fabricação e gastos operacionais. Embora exista em alguns países, sua aplicação contabilmente é inviável no Brasil, pois conflita com o regime de competência e com a legislação tributária. Com base na descrição apresentada, classifique o sistema de custeio mencionado.','[["A", "Por absorção."], ["B", "RKW."], ["C", "Direto."], ["D", "ABC."], ["E", "Padrão."]]'::jsonb,'B',2026,35,NULL,NULL,'{"regra": "No RKW (custeio pleno), todos os custos e também despesas são rateados aos produtos para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Pleno (RKW).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — RKW.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Pleno (RKW)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3281620',2371,76,'P2','Contabilidade de Custos - Custeio Pleno (RKW)','VUNESP - CFO/QC (EsFCEx)/EsFCEx/Ciências Contábeis/2024','Caderno Contabilidade de Custos 2','36) O método de custeio que consiste em ratear aos produtos, todos os gastos da empresa; não somente custos, mas também despesas comerciais, administrativas e até mesmo as financeiras, bem como juros sobre capital próprio. Na medida que todos os custos de produção, diretos ou indiretos, bem como despesas comerciais, administrativas e até mesmo financeiras, incluindo os juros sobre capital próprio são rateados nos produtos da empresa, esta estará adotando o método de custeio','[["A", "por absorção."], ["B", "baseado em atividades."], ["C", "total."], ["D", "RKW."], ["E", "direto."]]'::jsonb,'D',2024,36,NULL,NULL,'{"regra": "No RKW (custeio pleno), todos os custos e também despesas são rateados aos produtos para fins gerenciais.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custeio Pleno (RKW).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — RKW.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custeio Pleno (RKW)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3908079',2372,84,'P1','Contabilidade de Custos - Custo Padrão','FADESP - ACAE (SEFA PA)/SEFA PA/2026','Caderno Contabilidade de Custos 2','37) A empresa Cerâmica Marajoara Ltda, localizada no município de Soure, atua na produção de peças cerâmicas artesanais destinadas ao mercado regional. Para apoiar o processo decisório e o controle dos custos de produção, a gestão solicitou ao contador a apuração das variações entre o custo padrão e o custo real do principal insumo utilizado na fabricação de determinado produto: argila beneficiada. Com base em estudos técnicos e contratos de fornecimento, o contador estabeleceu como padrão o consumo de 20 kg de argila por unidade produzida, ao preço padrão de R$ 15,00 por kg. Ao final do período, ao preparar o relatório gerencial solicitado pela diretoria, o contador apurou que: - o preço real da argila apresentou uma redução de 20% em relação ao preço padrão. - o consumo real de argila foi 10% superior ao consumo padrão previamente estabelecido. Considerando os conceitos de custo padrão, variação de preço e variação de quantidade, e levando em conta exclusivamente a diferença entre o custo padrão total e o custo real total para a produção de uma unidade, é correto afirmar que a variação total do custo da argila foi de','[["A", "R$ 36,00 favorável."], ["B", "R$ 36,00 desfavorável."], ["C", "R$ 40,00 favorável."], ["D", "R$ 40,00 desfavorável."], ["E", "R$ 30,00 desfavorável."]]'::jsonb,'A',2026,37,NULL,NULL,'{"regra": "O custo-padrão é um parâmetro previamente estabelecido para planejamento e controle; sua comparação com o custo real evidencia variações favoráveis ou desfavoráveis.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custo Padrão.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — R$ 36,00 favorável.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custo Padrão"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3961290',2373,84,'P1','Contabilidade de Custos - Custo Padrão','Legalle - Tec Desen (BADESUL)/BADESUL/Contador/2026','Caderno Contabilidade de Custos 2','38) Suponha a realização de uma auditoria em uma indústria que captou recursos para a modernização de seu parque industrial. Para a liberação da 2ª parcela do financiamento, a indústria precisa comprovar a melhoria em seus controles de eficiência operacional. Analisando os relatórios gerenciais, o Contador identificou que a indústria, adota o sistema de custo padrão como instrumento de controle de sua produção. Sabe-se que, no mês 03/2026, foram apuradas variações relacionadas à mão de obra direta, sendo identificada uma variação de tempo de 100 horas acima da quantidade padrão estabelecida, que era de 700 horas, e uma variação do custo por hora de R$ 2,50 abaixo do valor orçado, fixado em R$ 10 por hora. Com base nessas informações, é CORRETO afirmar que o valor da variação total entre o custo padrão e o custo real foi favorável, no valor de:','[["A", "R$ 1.400."], ["B", "R$ 1.100."], ["C", "R$ 1.000."], ["D", "R$ 1.200."], ["E", "R$ 1.500."]]'::jsonb,'C',2026,38,NULL,NULL,'{"regra": "O custo-padrão é um parâmetro previamente estabelecido para planejamento e controle; sua comparação com o custo real evidencia variações favoráveis ou desfavoráveis.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custo Padrão.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — R$ 1.000.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custo Padrão"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3992111',2374,84,'P1','Contabilidade de Custos - Custo Padrão','FGV - Bach (CFC)/CFC/1º Exame de Suficiência/2026','Caderno Contabilidade de Custos 2','39) A Indústria “M” S.A. produz itens para cabelos crespos e cacheados. Ela utiliza como parâmetro de análise e tomada de decisão de custo, o custo padrão e o custo real. No mês de junho de 2024, ela apresentou os seguintes dados: Custo Padrão Custo Real Descrição Quantidade Custo Unitário Custo Total Quantidade Custo Unitário Custo Total Tensoativos 3,00 45,00 135,00 4,50 55,00 247,50 Óleo de Argan 6,00 6,55 39,30 9,00 5,47 49,30 Estabilizantes 255,00 0,15 38,25 127,50 0,11 14,03 de espuma Espessantes 56,00 0,15 5,60 28,00 0,50 14,00 A partir desses dados, em relação à variação dos itens dos insumos de produção da Indústria “M” S.A., é correto afirmar que','[["A", "o Óleo de Argan apresentou variações favoráveis para a Indústria “M” S.A.."], ["B", "os Estabilizantes de espuma apresentam variações favoráveis para a Indústria “M” S.A.."], ["C", "as variações de custo total do Estabilizantes de espuma e do Espessantes são desfavoráveis."], ["D", "as variações de custo total dos Tensoativos e do Óleo de Argan são favoráveis."]]'::jsonb,'B',2026,39,NULL,NULL,'{"regra": "O custo-padrão é um parâmetro previamente estabelecido para planejamento e controle; sua comparação com o custo real evidencia variações favoráveis ou desfavoráveis.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custo Padrão.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — os Estabilizantes de espuma apresentam variações favoráveis para a Indústria “M” S.A..", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custo Padrão"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4023748',2375,84,'P1','Contabilidade de Custos - Custo Padrão','CEBRASPE (CESPE) - Prof NS (ANSA)/ANSA/Contabilidade/2026','Caderno Contabilidade de Custos 2','40) Julgue o item a seguir, referente à contabilidade de custos. O custo padrão é utilizado como ferramenta de controle gerencial, permitindo a identificação de variações entre o custo real e o custo esperado.','[["C", "Certo"], ["E", "Errado"]]'::jsonb,'Certo',2026,40,NULL,NULL,'{"regra": "O custo-padrão é um parâmetro previamente estabelecido para planejamento e controle; sua comparação com o custo real evidencia variações favoráveis ou desfavoráveis.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custo Padrão.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é Certo."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "Certo — conforme o gabarito registrado no caderno.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custo Padrão"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3908077',2376,90,'P1','Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio','FADESP - ACAE (SEFA PA)/SEFA PA/2026','Caderno Contabilidade de Custos 2','41) A empresa Açaí do Norte Processadora Ltda, localizada no Estado do Pará, atua no beneficiamento e comercialização de polpa de açaí, operando com produção contínua e vendas regulares ao longo do ano. Para fins de análise gerencial e atendimento às exigências societárias, a empresa elabora demonstrações de resultado utilizando diferentes métodos de custeio, avaliando os impactos desses métodos sobre o custo dos produtos vendidos, os estoques e o resultado do período. No exercício analisado, a empresa apresentou produção superior ao volume de vendas, incorrendo em custos fixos de fabricação relevantes, além de custos e despesas variáveis associadas à produção e à comercialização. Com base nos conceitos, diferenciações, critérios de apropriação dos custos e impactos dos métodos de custeio nos resultados, analise as assertivas a seguir: I. No custeio por absorção, todos os custos de produção, fixos e variáveis, são apropriados aos produtos, de modo que parte dos custos fixos pode permanecer ativada nos estoques, quando o volume produzido é superior ao volume vendido. II. No custeio variável, os custos fixos de fabricação não integram o custo dos produtos, sendo reconhecidos integralmente como despesa do período, o que elimina qualquer efeito do volume de produção sobre a mensuração do lucro. III. O custeio por absorção é o único método aceito para fins de avaliação de estoques e apuração do resultado contábil, enquanto o custeio variável é destinado exclusivamente a análises gerenciais, sem efeitos sobre a mensuração do lucro. IV. Em cenários nos quais a produção excede as vendas, o lucro apurado pelo custeio por absorção tende a ser superior ao lucro apurado pelo custeio variável, em razão da capitalização parcial dos custos fixos nos estoques. São corretas as assertivas','[["A", "I e II, apenas."], ["B", "I e IV, apenas."], ["C", "II e III, apenas."], ["D", "I, III e IV, apenas."], ["E", "I, II e IV, apenas."]]'::jsonb,'B',2026,41,NULL,NULL,'{"regra": "Absorção incorpora custos fixos de produção aos estoques; variável leva esses custos fixos ao resultado do período. Assim, diferenças entre produção e vendas podem gerar lucros distintos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — I e IV, apenas.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3913235',2377,90,'P1','Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio','FADESP - AFRE PA/SEFA PA/2026','Caderno Contabilidade de Custos 2','42) A empresa industrial Augusto Corrêa Ltda, que trabalha com a produção e comercialização de plantas ornamentais, preparou sua produção para o dia das mães no exercício de 2025. Em 01/05/2025, iniciou sua produção e, em 30/05/2025, apresentou os seguintes dados contábeis operacionalizados no respectivo período: - Produção: 3.000 unidades totalmente acabadas. - Custos Variáveis: R$ 48.000,00. - Custos Fixos: R$ 60.000,00. - Despesas Variáveis: R$ 20.000,00. - Despesas Fixas: R$ 16.000,00. - Não há estoques iniciais e finais de produtos em elaboração. - Não há estoques iniciais de produtos acabados. - Vendas Líquidas: 2.500 unidades a R$ 80,00 cada, totalizando uma receita de R$ 200.000,00. A partir dos dados de produção e venda apresentados, o contador da industrial Augusto Corrêa Ltda decidiu conhecer o custo dos produtos vendidos (CPV) em maio de 2025. Para isso, fez uso dos métodos de custeio por absorção e do custeio variável. Sendo assim, é correto afirmar que o custo dos produtos vendidos (CPV) pelo custeio por absorção e pelo custeio variável, respectivamente, são','[["A", "R$ 107.000,00 e R$ 48.000,00."], ["B", "R$ 104.000,00 e R$ 57.000,00."], ["C", "R$ 90.000,00 e R$ 40.000,00."], ["D", "R$ 120.000,00 e R$ 68.000,00."], ["E", "R$ 108.000,00 e R$ 54.000,00."]]'::jsonb,'C',2026,42,NULL,NULL,'{"regra": "Absorção incorpora custos fixos de produção aos estoques; variável leva esses custos fixos ao resultado do período. Assim, diferenças entre produção e vendas podem gerar lucros distintos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — R$ 90.000,00 e R$ 40.000,00.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3606722',2378,90,'P1','Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio','AMEOSC - Cont (CM Mondaí)/CM Mondaí/2025','Caderno Contabilidade de Custos 2','43) A contabilidade de custos fornece instrumentos fundamentais para o planejamento e o controle das atividades operacionais, sendo os métodos de custeio e a análise do ponto de equilíbrio essenciais para decisões de natureza gerencial. Com base nas técnicas e métodos de custeio, assinale a alternativa correta.','[["A", "O método de custeio por atividade (ABC) permite rastrear os custos indiretos com maior precisão, atribuindo-os com base no consumo de atividades."], ["B", "No custeio por absorção, os custos fixos são tratados como despesas operacionais e não são incorporados ao custo do produto."], ["C", "O ponto de equilíbrio contábil é alcançado quando o lucro operacional corresponde ao valor total dos custos fixos mais variáveis."], ["D", "O custeio variável considera todos os custos, fixos e variáveis, como apropriáveis aos produtos, independentemente do volume de produção."]]'::jsonb,'A',2025,43,NULL,NULL,'{"regra": "Absorção incorpora custos fixos de produção aos estoques; variável leva esses custos fixos ao resultado do período. Assim, diferenças entre produção e vendas podem gerar lucros distintos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — O método de custeio por atividade (ABC) permite rastrear os custos indiretos com maior precisão, atribuindo-os com base no consumo de atividades.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3667081',2379,90,'P1','Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio','AMEOSC - Cont (CM Sta Helena)/CM Santa Helena (SC)/2025','Caderno Contabilidade de Custos 2','44) A escolha do método de custeio impacta diretamente o valor dos estoques, o custo dos produtos vendidos e, consequentemente, o resultado apurado pela entidade. Considerando os métodos de custeio por absorção e variável, analise as afirmativas a seguir. I.O método de custeio por absorção apropria aos produtos todos os custos de produção, sejam eles fixos ou variáveis, diretos ou indiretos. II.No custeio variável, apenas os custos variáveis de produção são alocados aos produtos, enquanto os custos fixos de produção são tratados como despesas do período. III.Em um período em que a quantidade produzida é maior que a quantidade vendida, o lucro apurado pelo método de custeio por absorção será maior que o lucro apurado pelo custeio variável. Está correto o que se afirma em:','[["A", "I e II apenas."], ["B", "I e III apenas."], ["C", "II e III apenas."], ["D", "I, II e III."]]'::jsonb,'D',2025,44,NULL,NULL,'{"regra": "Absorção incorpora custos fixos de produção aos estoques; variável leva esses custos fixos ao resultado do período. Assim, diferenças entre produção e vendas podem gerar lucros distintos.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio.", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é D."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "D — I, II e III.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Comparação entre Sistemas e Tópicos mesclados sobre Sistemas de Custeio"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3373246',2380,76,'P2','Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)','IGEDUC - Cont (CRMV BA)/CRMV BA/2025','Caderno Contabilidade de Custos 2','45) Uma indústria do setor calçadista está avaliando duas opções de investimento: a fabricação de um novo produto ou a expansão da produção de um item já existente. Para tomar a melhor decisão, a empresa deve considerar os conceitos de custos e receitas diferenciais e custo de oportunidade. A respeito desses conceitos, assinale a alternativa correta.','[["A", "O custo de oportunidade de uma decisão representa o benefício que poderia ser obtido caso a empresa escolhesse a melhor alternativa rejeitada."], ["B", "Custos e receitas diferenciais são aqueles que permanecem constantes independentemente da decisão tomada pela empresa."], ["C", "Custos diferenciais incluem apenas custos fixos, pois os custos variáveis não mudam com a decisão empresarial."], ["D", "O custo de oportunidade representa um gasto real e desembolsável que a empresa deve pagar ao optar por uma alternativa em vez de outra."]]'::jsonb,'A',2025,45,NULL,NULL,'{"regra": "Custos perdidos (sunk costs) decorrem de decisões passadas e são irrelevantes para decisões futuras; custo de oportunidade é o benefício da melhor alternativa rejeitada.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é A."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "A — O custo de oportunidade de uma decisão representa o benefício que poderia ser obtido caso a empresa escolhesse a melhor alternativa rejeitada.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3447021',2381,76,'P2','Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)','FACTO - Tecnic (IF ES)/IF ES/Contabilidade/2025','Caderno Contabilidade de Custos 2','46) De acordo com Crepaldi (2010), indique o conceito relacionado ao seguinte trecho: “Representa o valor associado à melhor alternativa não escolhida. Ao se tomar determinada escolha, deixa-se de lado as demais possibilidades, pois excludentes. O mais alto valor associado aos benefícios não escolhidos pode ser entendido como um custo da opção escolhida”:','[["A", "Custo marginal."], ["B", "Custo de oportunidade."], ["C", "Custo primário."], ["D", "Custo-padrão."], ["E", "Gasto."]]'::jsonb,'B',2025,46,NULL,NULL,'{"regra": "Custos perdidos (sunk costs) decorrem de decisões passadas e são irrelevantes para decisões futuras; custo de oportunidade é o benefício da melhor alternativa rejeitada.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é B."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "B — Custo de oportunidade.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
INSERT INTO questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3652682',2382,76,'P2','Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)','Marinha - QCOM (Marinha)/Marinha/Corpo de Intendentes da Marinha/Administração, Ciências Contábeis e Economia/2025','Caderno Contabilidade de Custos 2','47) A empresa Marinheiro Feliz está avaliando a viabilidade de investir em um novo equipamento para aumentar sua capacidade produtiva. Nesse contexto, é essencial compreender diferentes tipos de custos para uma decisão eficaz. Assim, assinale a opção correta, segundo Martins (2016).','[["A", "O custo de oportunidade representa os gastos efetivamente incorridos na aquisição de um bem ou serviço."], ["B", "Custos imputados são aqueles desembolsados diretamente pela empresa e registrados na contabilidade."], ["C", "Custos perdidos referem-se a investimentos feitos no passado que provocam custos contábeis, mas são irrelevantes para certas decisões, por não alterarem fluxos financeiros."], ["D", "O custo de oportunidade é irrelevante para a tomada de decisão, pois não envolve saída de caixa."], ["E", "Custos imputados são considerados nas demonstrações financeiras obrigatórias, pois impactam o resultado contábil da empresa."]]'::jsonb,'C',2025,47,NULL,NULL,'{"regra": "Custos perdidos (sunk costs) decorrem de decisões passadas e são irrelevantes para decisões futuras; custo de oportunidade é o benefício da melhor alternativa rejeitada.", "passos": ["Identifique o núcleo do tema: Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade).", "Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.", "O gabarito registrado é C."], "calculo": "Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.", "correta": "C — Custos perdidos referem-se a investimentos feitos no passado que provocam custos contábeis, mas são irrelevantes para certas decisões, por não alterarem fluxos financeiros.", "erradas": ["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."], "fundamento": "Contabilidade de Custos - Custos Imputados e Custos Perdidos (Sunk Costs; Custo de Oportunidade)"}'::jsonb,NULL) ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, resolution=EXCLUDED.resolution;
